  end if;
  raise notice 'Importazione completata.';
end
$imp$;

-- controllo
select (select count(*) from clienti_mascalcia where maniscalco_id = 'f170bc74-a189-4d68-bab5-31d9613726bb' and archiviato_il is null) strutture_attive,
       (select count(*) from cavalli_clienti_mascalcia where maniscalco_id = 'f170bc74-a189-4d68-bab5-31d9613726bb') cavalli,
       (select count(*) from interventi_mascalcia where maniscalco_id = 'f170bc74-a189-4d68-bab5-31d9613726bb' and note = 'Importato dalla vecchia app (23/10/2026)') ferrature_importate,
       (select coalesce(sum(importo), 0) from interventi_mascalcia where maniscalco_id = 'f170bc74-a189-4d68-bab5-31d9613726bb' and stato = 'fatto' and stato_pagamento = 'da_saldare') totale_da_saldare,
       (select count(*) from import_decisioni where maniscalco_id = 'f170bc74-a189-4d68-bab5-31d9613726bb') scelte_per_francesco;
